function identifyCountry(productName, productId) {
    const text = `${productName} ${productId}`.toLowerCase();
    for (const [key, info] of Object.entries(PAISES_FUTBOL)){
        if (text.includes(key) || text.includes(info.nombre_completo.toLowerCase()) || text.includes(info.seleccion.toLowerCase())) {
            return {
                key,
                info
            };
        }
    }
    const colors = [
        "celeste",
        "azul",
        "rojo",
        "verde",
        "amarillo",
        "naranja",
        "blanco",
        "negro"
    ];
    for (const color of colors){
        if (text.includes(color)) {
            for (const [key, info] of Object.entries(PAISES_FUTBOL)){
                if (info.colores.includes(color)) {
                    return {
                        key,
                        info
                    };
                }
            }
        }
    }
    return null;
}
